#!/bin/bash
set -e

# the list of exported-functions.json
# generated by our ~/ivy/goivy/z3vendor/z3/src/api/js/build-glue.sh script
EXPORTED_FUNCS=$(cat src/api/js/exported-functions.json)
: "${EMCC:=emcc}"
: "${Z3_API_BASENAME:=z3-api}"
EMCC_CACHE_ARGS=()
if [[ -n "${EM_CACHE:-}" ]]; then
  EMCC_CACHE_ARGS=(--cache "$EM_CACHE")
fi

"$EMCC" \
  "${EMCC_CACHE_ARGS[@]}" \
  -std=c++17 \
  -fwasm-exceptions \
  -D_NO_OMP_ \
  -D_MP_INTERNAL \
  -Isrc/api \
  -Lbuild \
  build/libz3.a \
  -sEXPORTED_FUNCTIONS="$EXPORTED_FUNCS" \
  -sEXPORTED_RUNTIME_METHODS='["ccall","cwrap","UTF8ToString","stringToUTF8","addFunction","removeFunction"]' \
  -sALLOW_MEMORY_GROWTH=1 \
  -sALLOW_TABLE_GROWTH=1 \
  -sMODULARIZE=1 \
  -sEXPORT_NAME="initZ3" \
  -o "build/$Z3_API_BASENAME.js"

echo "Built build/$Z3_API_BASENAME.js and build/$Z3_API_BASENAME.wasm"
